program='''from dataclasses import dataclass

@dataclass
class State:
    board: list
    pos: tuple
    target: tuple

def init(board):
    b=[r[:] for r in board]
    cs=[(y,x) for y in range(64) for x in range(64) if b[y][x]==12]
    pos=(min(y for y,x in cs),min(x for y,x in cs))
    # The goal is the small 7x7 gray interior enclosed by a color-3 border.
    candidates=[]
    for y in range(58):
        for x in range(58):
            if all(b[y+dy][x+dx]==5 for dy in range(7) for dx in range(7)):
                candidates.append((y,x))
    if not candidates:
        raise ValueError('goal not found')
    gy,gx=candidates[0]
    return State(b,pos,(gy+1,gx+1))

def render(state):
    return state.board

def step(state,action):
    a=action[0]
    dy,dx={1:(-5,0),2:(5,0),3:(0,-5),4:(0,5)}[a]
    y,x=state.pos; ny,nx=y+dy,x+dx
    if not (0<=ny<=59 and 0<=nx<=59):
        return state
    # Corridors and goal cells are every non-background color except the moving block.
    for yy in range(ny,ny+5):
        for xx in range(nx,nx+5):
            if state.board[yy][xx]==4:
                return state
    b=[r[:] for r in state.board]
    for yy in range(y,y+5):
        for xx in range(x,x+5): b[yy][xx]=3
    for yy in range(ny,ny+5):
        for xx in range(nx,nx+5): b[yy][xx]=12 if yy<ny+2 else 9
    return State(b,(ny,nx),state.target)

def won(state):
    return state.pos==state.target
'''
